def read_number(text):
    try:
        value = int(text)
    except ValueError:
        print('except')
        return None
    else:
        print('else')
        return value
    finally:
        print('finally')   # runs before either return completes

print(read_number('42'))   # else, finally, 42
print(read_number('x'))    # except, finally, None

