class ParseError(ValueError):
    pass

def parse_point(text):
    parts = text.split(',')
    if len(parts) != 2:
        raise ParseError(f'expected x,y, got {text!r}')
    try:
        return int(parts[0]), int(parts[1])
    except ValueError as err:
        raise ParseError(f'non-integer in {text!r}') from err

def load_points(lines):
    points, errors = [], []
    for line in lines:
        try:
            points.append(parse_point(line))
        except ParseError as err:
            errors.append(str(err))
    return points, errors

print(load_points(['1,2', '3', 'a,4']))
# ([(1, 2)], ["expected x,y, got '3'", "non-integer in 'a,4'"])

