class ValidationError(ValueError):
    def __init__(self, field, message):
        super().__init__(f'{field}: {message}')
        self.field = field
        self.message = message


def _require(order, field):
    try:
        return order[field]
    except KeyError as err:
        raise ValidationError(field, 'missing') from err


def _parse_qty(raw):
    if isinstance(raw, bool) or not isinstance(raw, (int, str)):
        raise ValidationError('qty', 'not an integer')
    try:
        qty = int(raw)
    except ValueError as err:
        raise ValidationError('qty', 'not an integer') from err
    if not 1 <= qty <= 999:
        raise ValidationError('qty', 'out of range')
    return qty


def check_order(order):
    try:
        sku = _require(order, 'sku')
        if not isinstance(sku, str) or not sku.strip():
            raise ValidationError('sku', 'must be a non-empty string')
        qty = _parse_qty(_require(order, 'qty'))
    except ValidationError as err:
        cause = type(err.__cause__).__name__ if err.__cause__ else None
        return {'ok': False, 'field': err.field, 'error': err.message, 'cause': cause}
    return {'ok': True, 'order': {'sku': sku.strip(), 'qty': qty}}

